const items = $input.all();
const caption = $("PostFeed").first().json.Caption;
let str = `{ 
  "message": "${caption}",
`;

items.forEach((item, index) => {
	const id = item.json.id;
	str += `  "attached_media[${index}]": {"media_fbid":"${id}"},\n`;
});

str = str.trim().replace(/,$/, "");
str += ` 
}`;

return [{
	json: {
		value: str
	}
}];

